import click
from click.testing import CliRunner


def test_non_integer_count_is_rejected_without_callback():
    called = []

    @click.command()
    @click.option("--count", type=int)
    def cli(count):
        called.append(count)

    result = CliRunner().invoke(cli, ["--count", "not-an-integer"])
    assert result.exit_code == 2
    assert called == []

